import sharp from 'sharp';
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const dir = new URL('./', import.meta.url);
const results = [];
for (const name of ['fire', 'fire-breathe', 'fire-blink']) {
  const path = fileURLToPath(new URL(`before/${name}.png`, dir));
  const { data, info } = await sharp(path).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const original = Buffer.from(data);
  const { width, height } = info;
  const count = width * height;
  const queue = new Int32Array(count);
  const visited = new Uint8Array(count);
  let head = 0, tail = 0;
  const pale = (i) => {
    const r = original[i * 4], g = original[i * 4 + 1], b = original[i * 4 + 2];
    return Math.min(r, g, b) >= 95 && Math.max(r, g, b) - Math.min(r, g, b) <= 55;
  };
  const add = (i) => {
    if (i < 0 || i >= count || visited[i] || original[i * 4 + 3] === 0 || !pale(i)) return;
    visited[i] = 1;
    queue[tail++] = i;
  };
  // Only pale pixels touching existing transparency can start a removal region.
  for (let y = 1; y < height - 1; y++) for (let x = 1; x < width - 1; x++) {
    const i = y * width + x;
    if (original[i * 4 + 3] === 0) continue;
    if ([i - 1, i + 1, i - width, i + width].some((n) => original[n * 4 + 3] === 0)) add(i);
  }
  // Known enclosed backdrop opening between the near wing and the hip.
  add(996 * width + 886);
  while (head < tail) {
    const i = queue[head++], x = i % width, y = Math.floor(i / width);
    data[i * 4 + 3] = 0;
    if (x > 0) add(i - 1);
    if (x < width - 1) add(i + 1);
    if (y > 0) add(i - width);
    if (y < height - 1) add(i + width);
  }
  const outputPath = fileURLToPath(new URL(`cleaned/${name}.png`, dir));
  await sharp(data, { raw: { width, height, channels: 4 } }).png().toFile(outputPath);
  const decoded = await sharp(outputPath).ensureAlpha().raw().toBuffer();
  let rgbChanges = 0, alphaChanges = 0;
  for (let i = 0; i < original.length; i++) {
    if (original[i] === decoded[i]) continue;
    if (i % 4 !== 3) rgbChanges++; else alphaChanges++;
  }
  if (rgbChanges !== 0 || alphaChanges !== tail) throw new Error('Unexpected pixel changes');
  await sharp(outputPath).flatten({ background: '#251917' }).resize(900).png().toFile(fileURLToPath(new URL(`${name}-after.png`, dir)));
  results.push({ name, width, height, removedEdgePixels: tail, rgbChanges, beforeSha256: createHash('sha256').update(await readFile(path)).digest('hex'), afterSha256: createHash('sha256').update(await readFile(outputPath)).digest('hex') });
}
await writeFile(new URL('results.json', dir), JSON.stringify(results, null, 2) + '\n');
console.log(JSON.stringify(results));

import sharp from 'sharp';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const dir = new URL('./', import.meta.url);
const standing = fileURLToPath(new URL('../../assets/dragons/source/baby/fire.png', dir));
const source = new URL('../Gemini_Generated_Image_ylxu5fylxu5fylxu.png', dir);
const extraction = JSON.parse(await readFile(new URL('extraction.json', dir), 'utf8'));
const scale = 1181 / extraction.boxes[0].height;
const toes = [[620, 635], [548, 565], [553, 559], [584, 550]];
const ids = ['early', 'middle', 'late', 'seated'];
const original = await sharp(standing).ensureAlpha().raw().toBuffer();
const layers = [];
const layout = [{ id: 'standing', source: 'fire.png', sha256: createHash('sha256').update(await readFile(standing)).digest('hex'), left: 0, top: 0 }];
for (let index = 1; index < 5; index++) {
  const framePath = fileURLToPath(new URL(`frame-${index}.png`, dir));
  const box = extraction.boxes[index];
  const width = Math.round(box.width * scale), height = Math.round(box.height * scale);
  const toe = toes[index - 1];
  const left = Math.round(1330 - toe[0] * scale), top = Math.round(1608 - toe[1] * scale);
  if (left < 0 || top < 0 || left + width > 2048 || top + height > 2048) throw new Error('Frame exceeds canvas');
  const input = await sharp(framePath).resize(width, height).png().toBuffer();
  layers.push({ input, left: index * 2048 + left, top });
  layout.push({ id: ids[index - 1], box, toe, left, top, width, height });
}
const pixels = await sharp({ create: { width: 10240, height: 2048, channels: 4, background: '#00000000' } }).composite(layers).raw().toBuffer();
for (let y = 0; y < 2048; y++) original.copy(pixels, y * 10240 * 4, y * 2048 * 4, (y + 1) * 2048 * 4);
const sheet = await sharp(pixels, { raw: { width: 10240, height: 2048, channels: 4 } }).png().toBuffer();
await writeFile(new URL('fire-sit-sequence.png', dir), sheet);
await sharp(sheet).resize({ width: 5120 }).webp({ lossless: true }).toFile(fileURLToPath(new URL('fire-sit-sequence.webp', dir)));
const first = await sharp(sheet).extract({ left: 0, top: 0, width: 2048, height: 2048 }).ensureAlpha().raw().toBuffer();
if (!first.equals(original)) throw new Error('Standing frame changed');
const provided = await sharp(fileURLToPath(source)).ensureAlpha().raw().toBuffer();
const cutout = await sharp(fileURLToPath(new URL('original-cutout.png', dir))).ensureAlpha().raw().toBuffer();
let rgbChanges = 0;
for (let i = 0; i < provided.length; i++) if (i % 4 !== 3 && provided[i] !== cutout[i]) rgbChanges++;
if (rgbChanges !== 0) throw new Error('Cutout RGB differs from source');
await writeFile(new URL('fire-sit-sequence.json', dir), JSON.stringify({
  providedSource: 'Gemini_Generated_Image_ylxu5fylxu5fylxu.png',
  sourceSha256: createHash('sha256').update(await readFile(source)).digest('hex'),
  method: 'Deterministic alpha-only checker mask and connected-component extraction; no generative editing or RGB correction.',
  extractionRgbChanges: rgbChanges, standingPixelsUnchanged: true,
  frameSize: 2048, frameDurationMs: 300, frontToe: [1330, 1608], scale, frames: layout,
}, null, 2) + '\n');
console.log('Original cutout RGB: 0 changed channels. Standing pixels unchanged. Five-frame sheet rebuilt.');

import sharp from 'sharp';
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const dir = new URL('./', import.meta.url);
const input = fileURLToPath(new URL('../Gemini_Generated_Image_ylxu5fylxu5fylxu.png', dir));
const { data, info } = await sharp(input).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
const { width, height } = info;
const count = width * height;
const background = new Uint8Array(count);
const queue = new Int32Array(count);
let head = 0, tail = 0;
function isBackdrop(i) {
  const r = data[i * 4], g = data[i * 4 + 1], b = data[i * 4 + 2];
  return Math.max(r, g, b) - Math.min(r, g, b) <= 8 && Math.min(r, g, b) >= 65 && Math.max(r, g, b) <= 125;
}
// Enclosed checker holes have the same neutral gray colors. Mark these first;
// enclosed dragon highlights are retained by filling small holes below.
for (let i = 0; i < count; i++) if (isBackdrop(i)) background[i] = 1;
const seen = new Uint8Array(count);
const components = [];
for (let i = 0; i < count; i++) {
  if (background[i] || seen[i]) continue;
  head = 0; tail = 1; queue[0] = i; seen[i] = 1;
  let left = width, top = height, right = 0, bottom = 0;
  const pixels = [];
  while (head < tail) {
    const k = queue[head++], x = k % width, y = Math.floor(k / width);
    pixels.push(k); left = Math.min(left, x); right = Math.max(right, x); top = Math.min(top, y); bottom = Math.max(bottom, y);
    for (const n of [x > 0 ? k - 1 : -1, x < width - 1 ? k + 1 : -1, y > 0 ? k - width : -1, y < height - 1 ? k + width : -1]) {
      if (n >= 0 && !background[n] && !seen[n]) { seen[n] = 1; queue[tail++] = n; }
    }
  }
  if (pixels.length > 10000) components.push({ left, top, width: right - left + 1, height: bottom - top + 1, pixels });
}
components.sort((a, b) => a.left - b.left);
if (components.length !== 5) throw new Error(`Expected five dragons, found ${components.length}`);
const mask = new Uint8Array(count);
for (const component of components) for (const i of component.pixels) mask[i] = 255;
// Restore small enclosed neutral highlights without filling the large checker openings.
seen.fill(0);
for (let i = 0; i < count; i++) {
  if (mask[i] || seen[i]) continue;
  head = 0; tail = 1; queue[0] = i; seen[i] = 1;
  let touchesEdge = false;
  while (head < tail) {
    const k = queue[head++], x = k % width, y = Math.floor(k / width);
    if (x === 0 || y === 0 || x === width - 1 || y === height - 1) touchesEdge = true;
    for (const n of [x > 0 ? k - 1 : -1, x < width - 1 ? k + 1 : -1, y > 0 ? k - width : -1, y < height - 1 ? k + width : -1]) {
      if (n >= 0 && !mask[n] && !seen[n]) { seen[n] = 1; queue[tail++] = n; }
    }
  }
  if (!touchesEdge && tail <= 120) for (let p = 0; p < tail; p++) mask[queue[p]] = 255;
}
const output = Buffer.from(data);
for (let i = 0; i < count; i++) output[i * 4 + 3] = mask[i];
let rgbChanges = 0;
for (let i = 0; i < count; i++) for (let channel = 0; channel < 3; channel++) if (output[i * 4 + channel] !== data[i * 4 + channel]) rgbChanges++;
if (rgbChanges !== 0) throw new Error('RGB changed');
await sharp(output, { raw: { width, height, channels: 4 } }).png().toFile(fileURLToPath(new URL('original-cutout.png', dir)));
const boxes = components.map(({ pixels, ...box }) => ({ ...box, area: pixels.length }));
await writeFile(new URL('extraction.json', dir), JSON.stringify({ input, width, height, rgbChanges, boxes }, null, 2) + '\n');
for (let index = 0; index < boxes.length; index++) {
  const { area, ...box } = boxes[index];
  await sharp(output, { raw: { width, height, channels: 4 } }).extract(box).png().toFile(fileURLToPath(new URL(`frame-${index}.png`, dir)));
}
console.log(JSON.stringify({ rgbChanges, boxes }));

