import sharp from 'sharp';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const dir = new URL('./', import.meta.url);
const source = fileURLToPath(new URL('fire-sit-transparent-generated.png', dir));
const standing = fileURLToPath(new URL('../../assets/dragons/source/baby/fire.png', dir));
const scale = 1181 / 301;
const frames = [
  { id: 'early', box: { left: 483, top: 216, width: 379, height: 302 }, toe: [288, 299] },
  { id: 'middle', box: { left: 931, top: 240, width: 339, height: 305 }, toe: [259, 267] },
  { id: 'late', box: { left: 1357, top: 245, width: 336, height: 302 }, toe: [262, 263] },
  { id: 'seated', box: { left: 1782, top: 247, width: 333, height: 300 }, toe: [278, 262] },
];
const standingBytes = await readFile(standing);
const layers = [{ input: standingBytes, left: 0, top: 0 }];
const layout = [{ id: 'standing', source: 'fire.png', sha256: createHash('sha256').update(standingBytes).digest('hex'), left: 0, top: 0, width: 2048, height: 2048 }];
for (const [index, frame] of frames.entries()) {
  const width = Math.round(frame.box.width * scale);
  const height = Math.round(frame.box.height * scale);
  const left = Math.round(1330 - frame.toe[0] * scale);
  const top = Math.round(1608 - frame.toe[1] * scale);
  if (left < 0 || top < 0 || left + width > 2048 || top + height > 2048) throw new Error('Frame exceeds canvas');
  const input = await sharp(source).extract(frame.box).resize(width, height).png().toBuffer();
  layers.push({ input, left: (index + 1) * 2048 + left, top });
  layout.push({ ...frame, left, top, width, height });
}
const pixels = await sharp({ create: { width: 10240, height: 2048, channels: 4, background: '#00000000' } }).composite(layers).raw().toBuffer();
const original = await sharp(standing).ensureAlpha().raw().toBuffer();
for (let y = 0; y < 2048; y++) original.copy(pixels, y * 10240 * 4, y * 2048 * 4, (y + 1) * 2048 * 4);
const sheet = await sharp(pixels, { raw: { width: 10240, height: 2048, channels: 4 } }).png().toBuffer();
await writeFile(new URL('fire-sit-sequence.png', dir), sheet);
await sharp(sheet).resize({ width: 5120 }).webp({ lossless: true }).toFile(fileURLToPath(new URL('fire-sit-sequence.webp', dir)));
await writeFile(new URL('fire-sit-sequence.json', dir), JSON.stringify({
  providedSource: 'Gemini_Generated_Image_ylxu5fylxu5fylxu.png',
  generatedSource: 'fire-sit-transparent-generated.png',
  sourceSha256: createHash('sha256').update(await readFile(source)).digest('hex'),
  frameSize: 2048, frameDurationMs: 300, frontToe: [1330, 1608], scale,
  note: 'First frame uses existing fire.png unchanged. Other frames use one scale and manually measured near-front-toe anchors. Generated cutout changes source details.',
  frames: layout,
}, null, 2) + '\n');
const firstFrame = await sharp(sheet).extract({ left: 0, top: 0, width: 2048, height: 2048 }).ensureAlpha().raw().toBuffer();
if (!firstFrame.equals(original)) throw new Error('First frame differs from current standing artwork');
const stats = await sharp(sheet).stats();
if (stats.isOpaque) throw new Error('Transparency missing');
console.log('Five-frame fire sit sheet built; transparency and unchanged standing frame verified.');

import sharp from 'sharp';
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const root = new URL('../../../', import.meta.url);
const dir = new URL('./', import.meta.url);
const standingPath = fileURLToPath(new URL('assets/dragons/source/baby/ice.png', root));
const standing = await sharp(standingPath).ensureAlpha().raw().toBuffer();
const layers = [];
const frames = [{ id: 'standing', source: 'ice.png', pixelsUnchanged: true }];
for (let index = 1; index < 4; index++) {
  const draft = await sharp(fileURLToPath(new URL(`frame-${index + 1}.png`, dir))).resize(2048, 2048).png().toBuffer();
  // Translate the approved draft anchor (1460,1620) to the app anchor (1330,1608).
  const input = await sharp(draft).extract({ left: 130, top: 12, width: 1918, height: 2036 }).png().toBuffer();
  layers.push({ input, left: index * 2048, top: 0 });
  frames.push({ id: ['A-1', 'A-3', 'A-4', 'A-5'][index], draft: `frame-${index + 1}.png`, scale: 2, translate: [-130, -12] });
}
const pixels = await sharp({ create: { width: 8192, height: 2048, channels: 4, background: '#00000000' } }).composite(layers).raw().toBuffer();
for (let y = 0; y < 2048; y++) standing.copy(pixels, y * 8192 * 4, y * 2048 * 4, (y + 1) * 2048 * 4);
const sheet = await sharp(pixels, { raw: { width: 8192, height: 2048, channels: 4 } }).png().toBuffer();
const first = await sharp(sheet).extract({ left: 0, top: 0, width: 2048, height: 2048 }).ensureAlpha().raw().toBuffer();
if (!first.equals(standing)) throw Error('Standing pixels changed');
const layout = JSON.parse(await readFile(new URL('layout.json', dir), 'utf8'));
await writeFile(new URL('assets/dragons/source/baby/ice-sit-sequence.png', root), sheet);
await writeFile(new URL('assets/dragons/source/baby/ice-sit-sequence.json', root), JSON.stringify({ frameSize: 2048, frameCount: 4, frameDurationMs: 300, frontToe: [1330, 1608], source: layout.source, draftSource: 'tmp_image/ice_sit/draft/', sourceSha256: createHash('sha256').update(await readFile(new URL('../Gemini_Generated_Image_iizebciizebciize.png', dir))).digest('hex'), method: layout.method, frames }, null, 2) + '\n');
console.log('Registered four frames; first frame RGBA matches existing ice.png.');

import sharp from 'sharp';
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const dir = new URL('./', import.meta.url);
const output = name => fileURLToPath(new URL(name, dir));
const choices = [
  { id: 'A-1', toe: [622, 783] },
  { id: 'A-3', toe: [606, 774] },
  { id: 'A-4', toe: [655, 769] },
  { id: 'A-5', toe: [707, 773] },
];
const frames = [];
const records = [];
for (const { id, toe } of choices) {
  const { data, info } = await sharp(fileURLToPath(new URL(`../review/crops/${id}.png`, dir))).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const rgba = Buffer.from(data);
  const count = info.width * info.height;
  const mask = new Uint8Array(count);
  for (let i = 0; i < count; i++) {
    const rgb = data.subarray(i * 4, i * 4 + 3);
    const min = Math.min(...rgb), max = Math.max(...rgb);
    mask[i] = min >= 235 && max - min <= 16 ? 0 : 255;
  }
  // Keep enclosed pale chest highlights; leave the large limb and wing gaps transparent.
  const seen = new Uint8Array(count);
  const queue = new Int32Array(count);
  for (let i = 0; i < count; i++) {
    if (mask[i] || seen[i]) continue;
    let read = 0, length = 1, edge = false;
    queue[0] = i; seen[i] = 1;
    while (read < length) {
      const p = queue[read++], x = p % info.width, y = Math.floor(p / info.width);
      if (x === 0 || y === 0 || x === info.width - 1 || y === info.height - 1) edge = true;
      for (const n of [x > 0 ? p - 1 : -1, x < info.width - 1 ? p + 1 : -1, y > 0 ? p - info.width : -1, y < info.height - 1 ? p + info.width : -1]) {
        if (n >= 0 && !mask[n] && !seen[n]) { seen[n] = 1; queue[length++] = n; }
      }
    }
    if (!edge && length <= 2048) for (let j = 0; j < length; j++) mask[queue[j]] = 255;
  }
  let rgbChanges = 0;
  for (let i = 0; i < count; i++) {
    rgba[i * 4 + 3] = mask[i];
    for (let c = 0; c < 3; c++) if (rgba[i * 4 + c] !== data[i * 4 + c]) rgbChanges++;
  }
  if (rgbChanges) throw Error('Original RGB changed');
  const cutout = await sharp(rgba, { raw: { width: info.width, height: info.height, channels: 4 } }).png().toBuffer();
  await writeFile(output(`${id}-cutout.png`), cutout);
  let xMin = info.width, xMax = 0, yMin = info.height, yMax = 0;
  for (let i = 0; i < count; i++) if (mask[i]) {
    const x = i % info.width, y = Math.floor(i / info.width);
    xMin = Math.min(xMin, x); xMax = Math.max(xMax, x);
    yMin = Math.min(yMin, y); yMax = Math.max(yMax, y);
  }
  const box = { left: xMin, top: yMin, width: xMax - xMin + 1, height: yMax - yMin + 1 };
  const left = 730 - toe[0] + xMin, top = 810 - toe[1] + yMin;
  if (left < 0 || top < 0 || left + box.width > 1024 || top + box.height > 1024) throw Error('Canvas overflow');
  const trimmed = await sharp(cutout).extract(box).png().toBuffer();
  const frame = await sharp({ create: { width: 1024, height: 1024, channels: 4, background: '#00000000' } }).composite([{ input: trimmed, left, top }]).png().toBuffer();
  frames.push(frame);
  await writeFile(output(`frame-${frames.length}.png`), frame);
  records.push({ id, toe, box, placement: { left, top }, rgbChanges });
}
await sharp({ create: { width: 4096, height: 1024, channels: 4, background: '#00000000' } }).composite(frames.map((input, i) => ({ input, left: i * 1024, top: 0 }))).png().toFile(output('ice-sit-sequence.png'));
const panels = [];
for (const [row, background] of ['#e8edf2', '#283747'].entries()) {
  for (let i = 0; i < 4; i++) {
    const frame = await sharp(frames[i]).resize(400, 400).flatten({ background }).png().toBuffer();
    panels.push({ input: frame, left: i * 400, top: row * 400 });
  }
}
await sharp({ create: { width: 1600, height: 800, channels: 3, background: '#ffffff' } }).composite(panels).png().toFile(output('comparison.png'));
const order = [0, 1, 2, 3, 2, 1];
const delay = [1200, 300, 300, 1500, 300, 300];
const animation = [];
for (const index of order) {
  animation.push(await sharp(frames[index]).resize(512, 512).flatten({ background: '#283747' }).ensureAlpha().raw().toBuffer());
}
const raw = { width: 512, height: 512 * order.length, channels: 4, pageHeight: 512 };
await sharp(Buffer.concat(animation), { raw }).gif({ delay, loop: 0, effort: 7 }).toFile(output('preview.gif'));
await sharp(Buffer.concat(animation), { raw }).webp({ delay, loop: 0, lossless: true }).toFile(output('preview.webp'));
const metadata = await sharp(output('preview.gif'), { animated: true }).metadata();
if (metadata.pages !== 6 || metadata.pageHeight !== 512 || metadata.delay.some((value, i) => value !== delay[i])) throw Error('Animation metadata mismatch');
await writeFile(output('layout.json'), JSON.stringify({ frameSize: 1024, source: '../Gemini_Generated_Image_iizebciizebciize.png', method: 'Alpha-only near-white removal; enclosed highlights up to 2048px restored; no RGB edits or frame rescaling.', anchor: [730, 810], frameDurationMs: 300, order, delay, frames: records, animationVerified: true }, null, 2) + '\n');
console.log('Four aligned frames; RGB changes: 0. Animation: six pages with verified timing.');

