 const {width:w,height:h}=info; const visited=new Uint8Array(w*h); const queue=new Int32Array(w*h); const components=[];
 const subject=i=>Math.max(data[i*4],data[i*4+1],data[i*4+2])<threshold;
 for(let i=0;i<w*h;i++) {
  if(visited[i]||!subject(i)) continue;
  let read=0,write=1; queue[0]=i; visited[i]=1;
  let l=w,t=h,r=0,b=0;
  while(read<write) {
   const p=queue[read++],x=p%w,y=Math.floor(p/w);
   l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);
   for(const n of [x>0?p-1:-1,x<w-1?p+1:-1,y>0?p-w:-1,y<h-1?p+w:-1])
