   if(decoded[(y*box.width+x)*4+c]!==data[((y+box.top)*w+x+box.left)*4+c]) changed++;
  if(changed) throw Error('Crop changed pixels');
  entry.frames.push({index:j+1,file:f,box,changedRgbaChannels:changed});
