import sharp from 'sharp';
import { writeFile, copyFile } from 'node:fs/promises';

const dir = new URL('./', import.meta.url);
const source = new URL('extracted-sheet.png', dir);
const { data, info } = await sharp(source.pathname).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
const bounds = [];
for (let frame = 0; frame < 4; frame++) {
  const x0 = Math.floor((frame % 2) * info.width / 2);
  const x1 = Math.floor((frame % 2 + 1) * info.width / 2);
  const y0 = Math.floor(Math.floor(frame / 2) * info.height / 2);
  const y1 = Math.floor((Math.floor(frame / 2) + 1) * info.height / 2);
  let left = x1, right = -1, top = y1, bottom = -1;
  for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
    if (data[(y * info.width + x) * 4 + 3] <= 32) continue;
    left = Math.min(left, x); right = Math.max(right, x);
    top = Math.min(top, y); bottom = Math.max(bottom, y);
  }
  if (right < left) throw new Error(`Empty frame ${frame}`);
  bounds.push({ left, top, width: right - left + 1, height: bottom - top + 1 });
}
const scale = 550 / Math.max(...bounds.map((b) => b.height));
const frames = [];
const placements = [];
for (let frame = 0; frame < 4; frame++) {
  const box = bounds[frame];
  const width = Math.round(box.width * scale);
  const height = Math.round(box.height * scale);
  if (width > 760) throw new Error('Insufficient horizontal margin');
  const input = await sharp(source.pathname).extract(box).resize(width, height).png().toBuffer();
  const left = Math.round((800 - width) / 2), top = 580 - height;
  const buffer = await sharp({ create: { width: 800, height: 620, channels: 4, background: '#00000000' } })
    .composite([{ input, left, top }]).png().toBuffer();
  await writeFile(new URL(`frame-${frame + 1}.png`, dir), buffer);
  frames.push(buffer); placements.push({ left, top, width, height });
}
// The fourth pose closely repeats the second; use three distinct leg positions.
const sequence = [0, 1, 2];
const sheet = await sharp({ create: { width: 2400, height: 620, channels: 4, background: '#00000000' } })
  .composite(sequence.map((index, slot) => ({ input: frames[index], left: slot * 800, top: 0 }))).png().toBuffer();
await writeFile(new URL('thunder-walk-bde.png', dir), sheet);
await sharp(sheet).webp({ lossless: true }).toFile(new URL('thunder-walk-bde.webp', dir).pathname);
const rawFrames = await Promise.all(sequence.map((index) => sharp(frames[index]).ensureAlpha().raw().toBuffer()));
await sharp(Buffer.concat(rawFrames), { raw: { width: 800, height: 620 * 3, channels: 4, pageHeight: 620 } })
  .webp({ lossless: true, loop: 0, delay: [200, 200, 200] }).toFile(new URL('walk-preview.webp', dir).pathname);
await writeFile(new URL('layout.json', dir), JSON.stringify({ source: 'extracted-sheet.png', extraction: 'built-in image_gen; generated extraction may differ from original details', bounds, scale, placements, sequence: sequence.map((i) => i + 1), width: 2400, height: 620, fps: 5, baseline: 580 }, null, 2) + '\n');
await copyFile(new URL('thunder-walk-bde.png', dir), new URL('../../../assets/dragons/source/baby/thunder-walk-bde.png', dir));
console.log('Four transparent frames; 2400×620 three-pose sheet and 5fps preview created.');

