import { chromium } from 'playwright';
import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';

const browser = await chromium.launch({ headless: true });
const results = [];
try {
  for (const width of [1280, 390]) {
    const page = await browser.newPage({ viewport: { width, height: 960 } });
    const errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    page.on('response', (r) => { if (r.status() >= 400 && r.url().includes('/assets/dragons/')) errors.push(`${r.status()} ${r.url()}`); });
    await page.goto('http://127.0.0.1:3100/dev/dragon-showcase');
    const panel = page.locator('.showcase-panel').first();
    await panel.locator('select').nth(1).selectOption('thunder');
    const scene = panel.locator('.dragon-scene');
    await scene.scrollIntoViewIfNeeded();
    const box = await scene.boundingBox();
    const x = box.x + box.width * .5, y = box.y + box.height * .5;
    await page.mouse.move(x, y);
    await page.mouse.down();
    await page.mouse.move(x + 45, y, { steps: 3 });
    const frame = panel.locator('.dragon-walk-frame');
    await frame.waitFor({ state: 'visible' });
    assert.match(await frame.evaluate((e) => e.style.backgroundImage), /thunder-walk-bde/);
    const style = await frame.evaluate((e) => ({ duration: getComputedStyle(e).animationDuration, size: getComputedStyle(e).backgroundSize }));
    assert.equal(style.duration, '0.6s');
    assert.equal(style.size, '300% 100%');
    const positions = new Set();
    for (let i = 0; i < 8; i++) {
      positions.add(await frame.evaluate((e) => getComputedStyle(e).backgroundPositionX));
      await page.waitForTimeout(100);
    }
    assert.equal(positions.size, 3);
    await page.screenshot({ path: new URL(`browser-${width}.png`, import.meta.url).pathname, fullPage: true });
    await page.emulateMedia({ reducedMotion: 'reduce' });
    assert.equal(await panel.locator('.dragon-walk').isVisible(), false);
    assert.equal(await panel.locator('.dragon-idle').isVisible(), true);
    await page.mouse.up();
    await page.emulateMedia({ reducedMotion: 'no-preference' });
    assert.equal(await panel.locator('.dragon-walk').count(), 0);
    await page.waitForTimeout(6500);
    assert.equal(await panel.locator('.dragon-sit').count(), 0);
    assert.equal(await panel.locator('link[href*="thunder-sit"]').count(), 0);
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth), false);
    assert.deepEqual(errors, []);
    results.push({ width, frames: [...positions], walking: true, reducedMotion: true, idleAfterRelease: true, missingAssets: errors });
    await page.close();
  }
  await writeFile(new URL('browser-results.json', import.meta.url), JSON.stringify(results, null, 2) + '\n');
  console.log(JSON.stringify(results));
} finally {
  await browser.close();
}

