const cellWidth = info.width / 3;
if (!Number.isInteger(cellWidth)) throw new Error('Expected three equal frame cells');
const bounds = [];
for (let frame = 0; frame < 3; frame++) {
  let left = cellWidth, top = info.height, right = -1, bottom = -1;
  for (let y = 0; y < info.height; y++) for (let x = 0; x < cellWidth; x++) {
    if (data[(y * info.width + frame * cellWidth + x) * 4 + 3] <= 32) continue;
    left = Math.min(left, x); right = Math.max(right, x);
    top = Math.min(top, y); bottom = Math.max(bottom, y);
  }
  if (right < left) throw new Error(`Empty frame ${frame}`);
  bounds.push({ left: frame * cellWidth + left, top, width: right - left + 1, height: bottom - top + 1 });
}
const scale = 550 / Math.max(...bounds.map((box) => box.height));
const placements = [];
for (let frame = 0; frame < 3; frame++) {
  const box = bounds[frame];
  const width = Math.round(box.width * scale);
  const height = Math.round(box.height * scale);
  if (width > 800) throw new Error('Frame too wide');
  const buffer = await sharp(source).extract(box).resize(width, height).png().toBuffer();
