await writeFile(new URL('fire-sheet-layout.json', dir), JSON.stringify({ source: 'fire-transparent-generated.png', width: 2400, height: 620, frameWidth: 800, fps: 5, scale, bounds, frames: placements.map(({ left, top }) => ({ left, top })), alphaMin: stats.channels[3].min, alphaMax: stats.channels[3].max }, null, 2) + '\n');
